package jp.tapmarker;
import java.util.*;
public class ClearArrowsTest {
 public static void main(String[] args){PhaseEngine e=new PhaseEngine();PhaseEngine.Phase p=new PhaseEngine.Phase();p.id="A";p.name="A";p.graphX=120;p.graphY=80;PhaseEngine.Phase q=new PhaseEngine.Phase();q.id="B";q.name="B";e.phases.put(p.id,p);e.phases.put(q.id,q);e.initial="A";PhaseEngine.Region r=new PhaseEngine.Region();r.id="region";r.bounds=new float[]{0,0,1,1};e.regions.put(r.id,r);for(PhaseEngine.Phase state:e.phases.values()){PhaseEngine.Watch w=new PhaseEngine.Watch();w.id=state.id;w.condition=PhaseEngine.TIMEOUT;w.action=PhaseEngine.WAIT;w.timeoutMs=1;state.watches.add(w);}e.enter("A",0);e.observe(new HashMap<>(),2);e.lastCompletedRule="old";e.clearTransitions();if(!p.watches.isEmpty()||!q.watches.isEmpty())throw new AssertionError("all arrows");if(e.poll()!=null)throw new AssertionError("pending arrow");if(e.phases.size()!=2||e.regions.size()!=1||!e.initial.equals("A")||!e.current.equals("A")||p.graphX!=120||p.graphY!=80)throw new AssertionError("preserve graph nodes and regions");if(!e.lastCompletedRule.isEmpty()||!e.sourcePhase.isEmpty())throw new AssertionError("clear history");e.clearTransitions();if(e.phases.size()!=2)throw new AssertionError("repeat clear");System.out.println("PASS all-state arrow clearing, queued event clearing, node/region/start/layout preservation, history clearing and repeat clearing; device UI not tested.");}
}
